NAME = 'SloKJV: Slovenian translation of Holy Bible King James Version (1769)'
BOOK = 'Ephesians'

CHAPTERS = {
    1: {
        1: 'Pavel, po Božji volji apostol Jezusa Kristusa, svetim, ki so v Efezu in zvestim v Kristusu Jezusu:',
        2: '›Milost bodi vam in mir od Boga, našega Očeta in od Gospoda Jezusa Kristusa.‹',
        3: 'Blagoslovljen bodi Bog in Oče našega Gospoda Jezusa Kristusa, ki nas je blagoslovil z vsemi duhovnimi blagoslovi v nebeških prostorih v Kristusu.',
        4: 'Kakor nas je pred ustanovitvijo sveta izbral v njem, da bi bili pred njim sveti in brez graje, v ljubezni,',
        5: 'nas je glede na dobro voljo svojega hotenja zase vnaprej določil za posvojitev otrok po Jezusu Kristusu,',
        6: 'v hvalo slave njegove milosti, v kateri nas je naredil sprejete v ljubljenem.',
        7: 'V katerem imamo po njegovi krvi odkupitev, odpuščanje grehov glede na bogastva njegove milosti;',
        8: 'v čemer je imel do nas obilje v vsej modrosti in razumnosti,',
        9: 'ko nam je dal spoznati skrivnost svoje volje, po svojem zadovoljstvu, ki ga je namenil v sebi;',
        10: '§ da v razdeljevanju polnosti časov lahko zbere skupaj v eno vse stvari v Kristusu, tako te, ki so na nebu, kakor te, ki so na zemlji; celó v njem;',
        11: 'v katerem smo dosegli tudi dediščino, vnaprej določeni glede na namen njega, ki vse stvari dela po sklepu svoje lastne volje;',
        12: 'da bi bili mi, ki smo prvi zaupali v Kristusa, v hvalo njegove slave.',
        13: 'V katerega ste tudi vi zaupali, potem ko ste slišali besedo resnice, evangelij rešitve svojih duš. V katerem ste bili potem, ko ste verovali, tudi zapečateni s tem Svetim Duhom obljube,',
        14: 'ki je poroštvo naše dediščine do odkupitve kupljene lastnine, v hvalo njegove slave.',
        15: 'Zato se tudi jaz, potem ko sem slišal o vaši veri v Gospoda Jezusa in ljubezni do vseh svetih,',
        16: 'ne preneham zahvaljevati za vas in vas omenjati v svojih molitvah;',
        17: 'da bi vam Bog našega Gospoda Jezusa Kristusa, Oče slave, lahko dal duha modrosti in razodetja v spoznanju njega.',
        18: 'Da bi bile oči vašega razumevanja razsvetljene, da boste lahko vedeli kakšno je upanje njegovega klicanja in kakšna bogastva slave njegove dediščine v svetih',
        19: 'in kakšna je silna veličina njegove moči do nas, ki verujemo, glede na delovanje njegove mogočne moči,',
        20: 'ki jo je učinkovito prikazal v Kristusu, ko ga je obudil od mrtvih in ga postavil na svojo lastno desnico v nebeških prostorih,',
        21: 'daleč nad vsako kneževino in oblast in moč in gospostvo ter [nad] vsako ime, ki je poimenovano ne samo na tem svetu, temveč tudi na tem, ki prihaja.',
        22: 'In vse stvari je položil pod njegova stopala in mu dal, da je nad vsemi stvarmi, glava cerkvi,',
        23: 'ki je njegovo telo, polnost njega, ki izpolnjuje vse v vsem.',
    },
    2: {
        1: 'In oživil je vas, ki ste bili mrtvi v prestopkih in grehih,',
        2: 'v katerih ste v preteklem času živeli glede na način tega sveta, glede na princa oblasti zraka, duha, ki sedaj deluje v otrocih neposlušnosti;',
        3: 'med katerimi smo tudi mi vsi imeli v preteklih časih svoje vedênje v poželenjih našega mesa in uresničevali smo želje mesa in mišljenja in smo bili po naravi otroci besa, tako kakor drugi.',
        4: 'Toda Bog, ki je bogat v usmiljenju, nas je zaradi svoje velike ljubezni, s katero nas je vzljubil,',
        5: 'celó ko smo bili mrtvi v grehih, skupaj s Kristusom oživil (po milosti ste rešeni)',
        6: 'in nas skupaj dvignil in nas skupaj posadil v nebeške prostore v Kristusu Jezusu,',
        7: 'da bi v prihajajočih časih lahko pokazal izjemna bogastva svoje milosti v svoji prijaznosti do nas po Kristusu Jezusu.',
        8: 'Kajti z milostjo ste rešeni po veri; in to ni od vas, to je Božji dar;',
        9: 'ne [pa] iz del, da se ne bi katerikoli človek bahal.',
        10: 'Kajti mi smo njegova izdelava, ustvarjeni v Kristusu Jezusu za dobra dela, ki jih je Bog poprej odredil, da bi v njih hodili.',
        11: 'Zatorej se spomnite, da ste bili v preteklem času pogani v mesu, ki ste imenovani Neobreza po tistih, ki [sebe] imenujejo Obreza v mesu, storjena z rokami;',
        12: 'da ste bili v tistem času brez Kristusa, neznanci pred Izraelovo republiko in tujci pred zavezami obljube in niste imeli upanja in ste bili brez Boga na svetu.',
        13: 'Toda sedaj ste v Kristusu Jezusu vi, ki ste bili včasih daleč proč, približani po Kristusovi krvi.',
        14: 'Kajti on je naš mir, ki je oba napravil eno in je med nami zlomil srednji zid pregrade',
        15: 'in v svojem mesu odpravil sovraštvo, celó zakon zapovedi, vsebovan v odredbah; zato da naredi v sebi iz dveh enega novega človeka in tako sklene mir;',
        16: 'in da lahko oba v enem telesu po križu spravi k Bogu ter s tem umori sovraštvo.',
        17: 'In prišel je ter oznanil mir vam, ki ste bili daleč stran in tem, ki so bili blizu.',
        18: 'Kajti po njem imamo oboji po enem Duhu dostop k Očetu.',
        19: 'Zdaj torej niste več tujci in tuji ljudje, temveč sodržavljani s svetimi in iz Božje družine',
        20: 'in zgrajeni ste na temelju apostolov ter prerokov, sam Jezus Kristus pa je glavni vogalni kamen;',
        21: 'v katerem vsa zgradba, primerno zasnovana skupaj, raste v svet tempelj v Gospodu,',
        22: 'v katerem ste tudi vi po Duhu skupaj sezidani za Božje prebivališče.',
    },
    3: {
        1: 'Zaradi tega razloga jaz, Pavel, jetnik Jezusa Kristusa za vas pogane,',
        2: 'če ste slišali o razdeljevanju Božje milosti, katera mi je dana posebej do vas,',
        3: 'kako, da mi je po razodetju dal spoznati skrivnost (kakor sem prej napisal z nekaj besedami,',
        4: 's čimer, ko berete, lahko razumete moj vpogled v Kristusovo skrivnost);',
        5: 'ki v drugih časih ni bila razglašena človeškim sinovom, kakor je sedaj po Duhu razodeta njegovim svetim apostolom in prerokom,',
        6: 'da naj bi bili pogani sodediči in iz istega telesa ter po evangeliju udeleženci njegove obljube v Kristusu,',
        7: 'katerega služabnik sem postal, glede na Božji dar milosti, dane meni, po dejavnem delovanju njegove moči.',
        8: '§ Meni, ki sem manj, kakor najmanjši izmed vseh svetih, je dana ta milost, da naj bi med pogani oznanjal nedoumljiva Kristusova bogastva',
        9: '§ in storil, da vsi ljudje vidijo, kakšna je družba skrivnosti, ki je bila od začetka sveta skrita v Bogu, ki je po Jezusu Kristusu ustvaril vse stvari;',
        10: 'z namenom, da se lahko zdaj kneževinam in oblastem v nebeških prostorih prek cerkve da spoznati mnogovrstna Božja modrost,',
        11: 'glede na večen namen, ki ga je nameraval v Kristusu Jezusu, našem Gospodu,',
        12: 'v katerem imamo pogum in dostop z zaupanjem po njegovi veri.',
        13: 'Zatorej želim, da ob mojih stiskah za vas, kar je vaša slava, ne opešate.',
        14: '§ Zaradi tega razloga upogibam svoja kolena k Očetu našega Gospoda Jezusa Kristusa,',
        15: 'po katerem je imenovana celotna družina na nebu in zemlji,',
        16: 'da vam bo zagotovil, glede na bogastva svoje slave, da boste v notranjem človeku okrepljeni z močjo njegovega Duha;',
        17: 'da lahko Kristus po veri prebiva v vaših srcih, da bi ukoreninjeni in utemeljeni v ljubezni,',
        18: 'lahko z vsemi svetimi zmogli doumeti, kolikšna je širina in dolžina in globina in višina',
        19: 'ter da spoznate Kristusovo ljubezen, ki presega spoznanje, da bi bili lahko izpolnjeni z vso Božjo polnostjo.',
        20: 'Torej njemu, ki je zmožen, glede na moč, ki deluje v nas, narediti presegajoče obilno povrh vsega, kar prosimo ali mislimo,',
        21: '§ njemu bodi slava v cerkvi po Kristusu Jezusu skozi vsa obdobja, od veka do veka. Amen.',
    },
    4: {
        1: 'Jaz torej, Gospodov jetnik, vas rotim, da živite vredno Božjemu pozivu, s katerim ste poklicani,',
        2: 'z vso ponižnostjo in krotkostjo, s potrpežljivostjo prenašajte drug drugega v ljubezni',
        3: 'in prizadevajte si ohraniti enotnost Duha z vezjo miru.',
        4: 'Obstaja eno telo in en Duh, točno tako kot ste poklicani v enem upanju vaše poklicanosti;',
        5: 'en Gospod, ena vera, en krst,',
        6: 'en Bog in Oče vseh, ki je nad vsemi in po vseh in v vas vseh.',
        7: 'Toda vsakomur izmed nas je dana milost glede na mero Kristusovega daru.',
        8: 'Zatorej pravi: ›Ko se je povzpel gor na višavo, je odpeljal ujeto ujetništvo in dal darove ljudem.‹',
        9: '(Torej, da se je povzpel, kaj je to razen, da se je tudi najprej spustil v nižje dele zemlje?',
        10: '§ On, ki se je spustil, je tudi isti, ki se je povzpel daleč nad vsa nebesa, da bi lahko izvršil vse stvari.)',
        11: 'In dal je nekatere apostole in nekatere preroke in nekatere evangeliste in nekatere pastirje in učitelje;',
        12: 'za izpopolnjevanje svetih, za delo služenja, za izgrajevanje Kristusovega telesa;',
        13: 'dokler mi vsi ne pridemo k enotnosti vere in spoznanja Božjega Sina, do popolnega človeka, do mere postave Kristusove polnosti.',
        14: 'Tako odslej ne bomo več otroci, premetavani sem ter tja in prenašani okoli z vsakim vetrom nauka, s človeško pretkanostjo in spretno prekanjenostjo, s čimer oni prežijo, da bi zavedli;',
        15: 'temveč, ker govorimo resnico v ljubezni, lahko v vseh stvareh rastemo vanj, ki je glava, celó Kristus,',
        16: 'iz katerega celotno telo, primerno združeno skupaj in strnjeno s tem, kar vsak sklep oskrbuje, glede na dejavno delovanje po meri vsakega dela, omogoča rast telesa v izgrajevanje sebe v ljubezni.',
        17: 'To torej pravim in pričujem v Gospodu, da odslej ne živite, kakor živijo drugi pogani, v ničevosti svojega uma,',
        18: 'ki imajo zatemnjeno razumevanje, odtujeni so od Božjega življenja preko nevednosti, ki je v njih, zaradi slepote njihovega srca;',
        19: 'ki so se prek svojega občutka predali v pohotnost, da s pohlepom počenjajo vso nečistost.',
        20: 'Toda vi se niste tako učili Kristusa,',
        21: 'če je tako, da ste ga slišali in ste bili po njem poučeni, kakor je resnica v Jezusu;',
        22: 'da glede na prejšnje vedênje odložite starega človeka, ki je pokvarjen glede varljivih poželenj;',
        23: 'in bodite obnovljeni v duhu svojega uma;',
        24: 'in da si oblečete novega človeka, ki je po Bogu ustvarjen v pravičnosti in resnični svetosti.',
        25: 'Zatorej zavračajte laganje in vsak [naj] govori resnico s svojim bližnjim, kajti mi smo udje drug drugega.',
        26: '§ Bodite jezni in ne grešite; sonce naj ne zaide nad vašim besom',
        27: 'niti ne dajajte prostora hudiču.',
        28: 'Kdor je kradel, naj ne krade več, temveč naj se raje trudi in s svojimi rokami dela stvar, ki je dobra, da bo imel [kaj] dati tistemu, ki potrebuje.',
        29: 'Nobenemu umazanemu govoru ne dopustite iziti iz svojih ust, temveč to, kar je dobro, v prid izgrajevanju, da lahko nudi milost poslušalcem.',
        30: 'In ne žalostite Božjega Svetega Duha, s katerim ste zapečateni za dan odkupitve.',
        31: 'Naj bo vsa grenkoba in bes in jeza in razgrajanje ter zlo govorjenje vzdignjeno od vas z vso zlobnostjo [vred];',
        32: 'in bodite prijazni drug do drugega, nežnega srca, odpuščajoč drug drugemu, celó kakor je Bog zaradi Kristusa odpustil vam.',
    },
    5: {
        1: 'Bodite torej Božji posnemovalci, kakor ljubljeni otroci',
        2: 'in živite v ljubezni, kakor nas je tudi Kristus ljubil in dal samega sebe za nas kot daritev in žrtev Bogu v blagodišeč vonj.',
        3: 'Toda prešuštvovanje in vse nečistosti ali pohlepnosti naj ne bodo niti enkrat omenjene med vami, kakor se spodobi svetim;',
        4: 'niti umazanost, niti nespametno govorjenje, niti šaljiva vulgarnost, ki niso primerne, temveč rajši zahvaljevanje.',
        5: 'Kajti to veste, da ne vlačugar ne nečista oseba niti pohlepnež, ki je malikovalec, nima nobene dediščine v Kristusovem in Božjem kraljestvu.',
        6: 'Naj vas noben človek ne vara s praznimi besedami, kajti zaradi teh stvari prihaja Božji bes na otroke neposlušnosti.',
        7: 'Ne bodite torej udeleženci z njimi.',
        8: 'Kajti včasih ste bili tema, toda sedaj ste svetloba v Gospodu. Živite kot otroci svetlobe,',
        9: '§ (kajti sad Duha je v vsej dobroti in pravičnosti ter resnici)',
        10: 'in preizkušajte, kaj je sprejemljivo Gospodu.',
        11: 'In ne imejte družbe z brezplodnimi deli teme, temveč jih raje grajajte.',
        12: 'Kajti sramota je celó govoriti o teh stvareh, ki so po njih storjene na skrivnem.',
        13: 'Toda vse stvari, ki so pograjane, so razodete po svetlobi; kajti karkoli razodeva je svetloba.',
        14: 'Zatorej on pravi: ›Prebúdi se ti, ki spiš in vstani od mrtvih in Kristus ti bo dal svetlobo.‹',
        15: 'Glejte torej, da živite preudarno, ne kakor bedaki, temveč kakor modri.',
        16: 'Izkoristite čas, kajti dnevi so hudi.',
        17: 'Zatorej ne bodite nemodri, temveč razumevajte, kaj je Gospodova volja.',
        18: 'In ne bodite opiti z vinom, v čemer je izgred, temveč bodite napolnjeni z Duhom.',
        19: 'Nagovarjajte se s psalmi in hvalnicami ter duhovnimi pesmimi, prepevajte in v svojem srcu skladajte napeve Gospodu.',
        20: 'Vedno se zahvaljujte Bogu in Očetu v imenu našega Gospoda Jezusa Kristusa za vse stvari.',
        21: 'Drug drugemu se podrejajte v strahu Božjem.',
        22: 'Žene, podredite se svojim lastnim soprogom kakor Gospodu.',
        23: 'Kajti soprog je glava ženi, kakor je tudi Kristus glava cerkvi; in on je rešitelj telesa.',
        24: 'Torej kakor je cerkev podrejena Kristusu, tako naj bodo v vsaki stvari žene svojim lastnim soprogom.',
        25: 'Soprogi, ljubite svoje žene, prav tako kakor je tudi Kristus ljubil cerkev in dal zanjo samega sebe,',
        26: 'da bi jo lahko posvetil in očistil z vodnim izpiranjem po besedi,',
        27: 'da bi lahko sebi predstavil krasno cerkev, ki nima madeža ali gube ali katerekoli takšne stvari, temveč da bi bila sveta in brez pomanjkljivosti.',
        28: 'Tako so možje dolžni ljubiti svoje žene kakor svoja lastna telesa. Kdor ljubi svojo ženo, ljubi sebe.',
        29: '§ Kajti še nikoli ni noben človek sovražil svojega lastnega mesa, temveč ga hrani in neguje, kakor Gospod cerkev;',
        30: '§ kajti mi smo udje njegovega telesa, iz njegovega mesa in iz njegovih kosti.',
        31: 'Zaradi tega razloga bo mož zapustil svojega očeta in mater in bo pridružen k svoji ženi in ona dva bosta eno meso.',
        32: 'To je velika skrivnost, vendar jaz govorim glede Kristusa in cerkve.',
        33: 'Vseeno naj vsak izmed vas še posebej ljubi svojo ženo, celo kakor samega sebe; in žena [naj] gleda, da spoštuje svojega soproga.',
    },
    6: {
        1: 'Otroci, ubogajte svoje starše v Gospodu, kajti to je prav.',
        2: 'Spoštuj svojega očeta in mater (kar je prva zapoved z obljubo),',
        3: 'da bo lahko dobro s teboj in boš lahko dolgo živel na zemlji.',
        4: 'In vi očetje, ne provocirajte svojih otrok do besa, temveč jih vzgajajte v Gospodovem poučevanju in svarilu.',
        5: 'Služabniki, bodite poslušni tem, ki so vaši gospodarji glede na meso, s strahom in trepetom, v iskrenosti svojega srca kakor Kristusu;',
        6: 'ne z navidezno vdanostjo, kakor bi raje ugajali ljudem, temveč kot Kristusovi služabniki iz srca izpolnjujte Božjo voljo;',
        7: 'z dobro voljo izvršujte službo kakor Gospodu in ne ljudem,',
        8: 'ker veste, da katerokoli dobro stvar kdorkoli stori, isto bo prejel od Gospoda, bodisi je suženj ali svoboden.',
        9: 'In vi, gospodarji, jim storite iste stvari in prizanašajte grožnjam, ker veste, da je tudi vaš Gospodar v nebesih; niti pri njem ni oziranja na osebe.',
        10: 'Končno, moji bratje, bodite močni v Gospodu in v sili njegove moči.',
        11: 'Nadenite si vso Božjo bojno opremo, da boste zmožni obstati proti hudičevim zvijačam.',
        12: 'Kajti ne borimo se proti mesu in krvi, temveč proti kneževinam, proti oblastem, proti vladarjem teme tega sveta, proti duhovni zlobnosti na visokih položajih.',
        13: 'Zato vzemite nase celotno Božjo bojno opremo, da se boste zmožni na hudoben dan zoperstaviti in vse storiti ter obstati.',
        14: 'Stojte torej in imejte svoja ledja opasana z resnico in na sebi imejte prsni oklep pravičnosti',
        15: 'in svoja stopala, obuta s pripravljenostjo evangelija miru;',
        16: 'predvsem vzemite ščit vere, s katerim boste zmožni pogasiti vse ognjene puščice zlobnega.',
        17: 'In vzemite čelado rešitve duše in meč Duha, kar je Božja beseda;',
        18: 'in vedno molíte z vso molitvijo in ponižno prošnjo v Duhu in k temu bedite z vso vztrajnostjo in ponižno prošnjo za vse svete;',
        19: 'in zame, da mi bo lahko dana izgovarjava, da bom lahko pogumno odpiral svoja usta, da se razglasi skrivnost evangelija,',
        20: 'za katerega sem predstavnik v vezeh, da bom v tem lahko pogumno govoril, kakor bi moral govoriti.',
        21: 'Toda, da boste lahko poznali tudi moje zadeve in kako delam, vam bo Tihik, moj ljubljeni brat in zvesti služabnik v Gospodu, oznanil vse stvari;',
        22: 'katerega sem poslal k vam zaradi istega namena, da bi vi lahko spoznali naše zadeve in da bi on lahko potolažil vaša srca.',
        23: 'Mir bodi bratom in ljubezen z vero od Boga Očeta in Gospoda Jezusa Kristusa.',
        24: '§ Milost bodi z vsemi tistimi, ki z iskrenostjo ljubijo našega Gospoda Jezusa Kristusa. Amen. [Napisano iz Rima Efežanom po Tihiku.]',
    },
}
